def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find horizontal rows with internal one-cell gaps.
    events = [[] for _ in range(w)]
    horizontal_rows = set()
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != 0]
        if len(cols) < 2:
            continue
        found = []
        for c in range(cols[0] + 1, cols[-1]):
            if row[c] == 0 and row[c - 1] != 0 and row[c + 1] != 0:
                if row[c - 1] == row[c + 1]:
                    found.append((c, row[c - 1]))
        if found:
            horizontal_rows.add(r)
            for c, color in found:
                events[c].append((r, color))

    for c in range(w):
        ev = sorted(events[c])
        prev_r = -1
        for r, color in ev:
            for rr in range(prev_r + 1, r + 1):
                if out[rr][c] == 0:
                    out[rr][c] = color
            prev_r = r

        # A vertical object below the horizontal rows anchors the final segment.
        anchors = [(r, grid[r][c]) for r in range(h)
                   if r not in horizontal_rows and grid[r][c] != 0]
        if anchors:
            anchor_color = anchors[-1][1]
            for rr in range(prev_r + 1, h):
                if out[rr][c] == 0:
                    out[rr][c] = anchor_color

    return out
